from __future__ import annotations

from typing import Any, Callable


class RegistryError(ValueError):
    """Raised when a duplicate plugin name is registered."""


class Registry:
    """Registry for plugin callables keyed by name."""

    def __init__(self) -> None:
        self._plugins: dict[str, Callable[..., Any]] = {}

    def register(self, name: str, fn: Callable[..., Any]) -> None:
        """Register a callable under *name*. Raises ValueError if duplicate."""
        if name in self._plugins:
            raise RegistryError(f"Plugin name '{name}' is already registered.")
        self._plugins[name] = fn

    def get(self, name: str) -> Callable[..., Any]:
        """Return the callable registered under *name*. Raises KeyError if unknown."""
        try:
            return self._plugins[name]
        except KeyError:
            raise KeyError(f"Unknown plugin name '{name}'.") from None

    def run(self, name: str, *args: Any) -> Any:
        """Run the callable registered under *name* with *args*."""
        fn = self.get(name)
        return fn(*args)


registry = Registry()

